export const BODY: string = "\n<p>صورة تُظهر لحظة: وبياناتها الوصفية قد تُظهر أين تعيش وأين يذهب أطفالك إلى المدرسة ومتى يكون منزلك فارغًا.</p>\n<p>معظم الناس يشاركون صورًا دون مراجعة ما يسافر داخل الملف أبدًا: الخطر غير مرئي، ولهذا بالضبط يسهل تجاهله.</p>\n<p>يشرح هذا المقال مخاطر الخصوصية الحقيقية في إحداثيات GPS وبيانات EXIF والبيانات الوصفية المخفية، ومن يستطيع استغلالها، والخطوات العملية التي توقف التسرب.</p>\n<h2 id=\"the-hidden-layer\">الطبقة المخفية في كل صورة</h2>\n<p>كل صورة من هاتف أو كاميرا تحمل طبقة مخفية من البيانات: علامة الكاميرا وموديلها وضبط التعريض ووقت الالتقاط، وغالبًا إحداثيات GPS، تُكتب في الملف.</p>\n<p>لا تستطيع رؤية هذه البيانات بالنظر إلى الصورة: تعيش في ترويسة الملف، وعارض وحده يستطيع قراءتها: وذلك الخفاء هو جوهر الخطر. و<a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a> يجعل تلك الطبقة مرئية: يحلل البايتات الخام محليًا ويُظهر كل حقل، مع وسوم Privacy Tag كهرمانية في الحساسة.</p>\n<p>معظم المالكين يتفاجأ بما يجدونه: صورة عفوية للحديقة قد تحمل إحداثيات دقيقة وطابعًا زمنيًا دقيقًا ورقمًا تسلسليًا للهاتف الذي التقطها.</p>\n<p>والبيانات ليست خبيثة: الكاميرات تكتبها لأسباب مشروعة، مثل تنظيم الصور وتسجيل الضبط: ويبدأ الخطر عندما تغادر الصورة تخزينك الخاص.</p>\n<h2 id=\"gps-risk\">إحداثيات GPS: أخطر خطر</h2>\n<p>إحداثيات GPS هي أكثر ما قد تحمله صورة حساسية: زوج واحد من الأرقام قد يشير إلى منزل أو مدرسة أو عمل أو المكان الدقيق الذي التُقطت فيه الصورة.</p>\n<p>الهواتف تسجل GPS افتراضيًا في معظم تطبيقات الكاميرا: تُحفظ الإحداثيات بصمت في دليل GPSIFD، بدرجات ودقائق وثوانٍ، دون أي علامة مرئية في الصورة. وأي شخص ينزّل الصورة يستطيع قراءة تلك الإحداثيات بعارض مجاني ووضعها على خريطة: والنتيجة نقطة دقيقة، دقيقة بما يكفي لتحديد مبنى.</p>\n<p>وصورة واحدة تكشف مكانًا: وصور كثيرة تكشف نمطًا: منزل وعمل وصالة رياضية ومدرسة والطرق بينها: ذلك النمط خريطة لحياتك. والارتفاع يُسجل غالبًا أيضًا: قد يقول إن كانت صورة التُقطت على مستوى الأرض أو في طابق عالٍ، ما يضيّق الموقع أكثر.</p>\n<p>راجع كل صورة بحثًا عن تنبيه GPS قبل مشاركتها: وإذا وُجدت إحداثيات، أزلها بأداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> قبل أن تصل الصورة إلى أي مكان عام.</p>\n<h2 id=\"exif-risk\">بيانات EXIF: طوابع زمنية وهوية جهاز</h2>\n<p>GPS يأخذ الانتباه، لكن EXIF يحفظ مخاطر أهدأ: الطابع الزمني للالتقاط واحد منها، لأن نمط طوابع زمنية يكشف روتينًا.</p>\n<p>صور ملتقطة في نفس الوقت كل يوم تُظهر متى تغادر المنزل ومتى تعود ومتى تسافر: وروتين يخبر مراقبًا متى يُحتمل أن يكون منزل فارغًا. وأرقام تسلسلية للكاميرا خطر هادئ آخر: تربط صورًا بجهاز محدد، وإذا ظهر نفس الرقم التسلسلي تحت أسماء مختلفة، يصبح الارتباط بين تلك الهويات مرئيًا.</p>\n<p>وحقول البرنامج تكشف أدوات تعديلك ونظام تشغيلك: ذلك ثانوي وحده، لكن مدمجًا مع طوابع زمنية ومواقع يضيف إلى ملف مفصل. وحقول الفنان وحقوق النشر قد تحفظ اسمًا حقيقيًا: المحترفون يضيفونها عمدًا، لكن هاتفًا يرث اسم مالك قد يكتبه في كل صورة دون أن يلاحظ.</p>\n<p>ولرؤية كل حقل بعمق، اقرأ <a href=\"/ar/blog/bayanat-exif-mashruha/\">بيانات EXIF موضحة: ما تكشفه صورك</a>.</p>\n<h2 id=\"who-can-read\">من يستطيع قراءة بيانات صورك الوصفية؟</h2>\n<p>أي شخص يستطيع تنزيل الصورة يستطيع قراءة بياناتها الوصفية: ذلك هو الخطر كله في جملة واحدة، ويستحق فهم من يشمل.</p>\n<p>مشترون في متاجر عبر الإنترنت ينزّلون صور إعلانات بدقة كاملة: وإذا صوّر بائع منتجًا في المنزل، فقد يقرأ المشتري إحداثيات GPS لمنزل البائع. وقراء منتديات وإعلانات مبوبة يفعلون نفسه: كثير من المنتديات ومواقع الإعلانات تحافظ على الملف الأصلي سليمًا، فتبقى EXIF وGPS في الرحلة.</p>\n<p>ومتلقو البريد يستلمون الملف الأصلي كمرفق: وخلافًا لتطبيقات المراسلة، يحافظ البريد عادة على الملف كما هو، بيانات وصفية مشمولة. والمنصات الاجتماعية هي الاستثناء: WhatsApp وإنستغرام وفيسبوك تزيل ترويسات EXIF وGPS تلقائيًا عند الرفع، فالصور المشتركة هناك تصل نظيفة عادة.</p>\n<p>لكن الاستثناء له حدود: إذا شاركت الملف الأصلي بطريق آخر، مثل رابط سحابة أو تنزيل مباشر أو رفع إلى موقع، فالبيانات الوصفية تسافر معه.</p>\n<h2 id=\"children-risk\">صور الأطفال: ما هو على المحك أكثر</h2>\n<p>صور الأطفال هي ما هو على المحك أكثر، لأن الأطفال لا يستطيعون الحكم على الخطر بأنفسهم: صورة ملتقطة في المنزل أو المدرسة أو حديقة قد تحمل إحداثيات ذلك المكان.</p>\n<p>صورة مدرسية واحدة ببيانات GPS قد تكشف موقع المدرسة: وسلسلة صور قد تكشف روتين الطفل: وقت الدخول ووقت الخروج والأنشطة المعتادة. والطوابع الزمنية تضاف إلى الصورة: صور ملتقطة كل يوم أسبوع في نفس الوقت تُظهر جدولًا، والجداول تنفع القارئ الخطأ.</p>\n<p>يجب على الآباء مراجعة كل صورة لطفل قبل نشرها: افتح <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a> وابحث عن تنبيه GPS وأزل كل حساس قبل المشاركة. وفكر في تعطيل الموقع تمامًا لتطبيق الكاميرا: ذلك يوقف وسوم GPS من المصدر، فالصور المستقبلية لا تحتاج تنظيف موقع.</p>\n<p>وراجع الصورة نفسها أيضًا، لا البيانات الوصفية فقط: زي مدرسي أو لافتة شارع أو رقم منزل في البكسلات مرئي للجميع، ولا أداة بيانات وصفية تستطيع إزالته.</p>\n<h2 id=\"sellers-journalists\">بائعون وصحفيون وشخصيات عامة</h2>\n<p>بائعو متاجر عبر الإنترنت يصورون منتجات في المنزل أو المرآب أو الحديقة: تلك الصور قد تحمل إحداثيات GPS تشير مباشرة إلى عنوان البائع.</p>\n<p>والتنظيف الدفعي يحل هذا: اسحب مجموعة صور الإعلان كلها إلى أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> وانتظر الشارات الخضراء ونزّل ZIP الملفات النظيفة. والصحفيون يواجهون خطرًا مختلفًا: صورة لمكان حساس قد تكشف مصدرًا أو مكان لقاء أو منزلًا آمنًا: وإزالة البيانات الوصفية قبل النشر حماية أساسية.</p>\n<p>والشخصيات العامة والمبدعون يواجهون خطر حجم: مئات الصور عبر شهور وسنوات تبني خريطة مفصلة لتحركات ومنازل وعادات، مع أن كل صورة وحدها تبدو بريئة.</p>\n<p>وللمجموعات الثلاث، القاعدة نفسها: راجع ونظف وتحقق: راجع الأصل ونظفه ثم راجع النسخة النظيفة لتأكيد اختفاء الوسوم.</p>\n<h2 id=\"metadata-myths-risks\">أساطير تتركك مكشوفًا</h2>\n<p>عدة أساطير عن خصوصية الصور تستمر، وكل منها يترك الناس مكشوفين: ويستحق تصحيحها مباشرة.</p>\n<p>الأسطورة الأولى: تغيير الحجم يزيل البيانات الوصفية: غالبًا لا: صورة مغيرة الحجم قد تحمل نفس إحداثيات GPS مثل الأصل، ما لم تزيلها أداة تغيير الحجم. والأسطورة الثانية: تحويل الصيغة يزيل البيانات الوصفية: تحويل JPG إلى PNG قد يزيل EXIF، لكنه قد ينقله أيضًا في مقطع eXIf: لا تفترض أبدًا أن تحويلًا نظّف شيئًا.</p>\n<p>والأسطورة الثالثة: القص يزيل بيانات الموقع: القص يغيّر البكسلات لا الترويسات: وسوم GPS تنجو من قص، ما لم تزيلها الأداة. والأسطورة الرابعة: صورة بلا موقع مرئي آمنة: الموقع في الترويسة لا في الصورة: صورة لجدار أبيض قد تحمل مع ذلك إحداثيات دقيقة.</p>\n<p>والأسطورة الخامسة: فقط الصور المنشورة تهم: صورة مرسلة إلى شخص واحد قد تُعاد إرسالها، ومرفق بريد قد يُحفظ ويُشارك مجددًا: وبمجرد أن يغادر ملف جهازك، لا تستطيع استعادته.</p>\n<h2 id=\"what-survives-where\">أين تنجو البيانات الوصفية وأين تموت</h2>\n<p>معرفة أين تنجو البيانات الوصفية يساعد على الحكم على كل طريق مشاركة: القواعد بسيطة، لكنها ليست بديهية.</p>\n<p>تطبيقات المراسلة تزيلها: WhatsApp وإنستغرام وفيسبوك تزيل ترويسات EXIF والكاميرا وGPS تلقائيًا عندما ترفع عبر خوادمها. والبريد يحافظ عليها: المرفقات تسافر عادة سليمة، فيستلم المتلقي الأصل الكامل، بيانات وصفية مشمولة.</p>\n<p>والمتاجر عبر الإنترنت والمنتديات تحافظ عليها عادة: كثير منها يحفظ الملف المرفوع كما استُلم، فيستطيع مشترون وقراء تنزيل الأصل بوسومه. وروابط السحابة تحافظ عليها: مشاركة ملف عبر رابط Drive تعطي المتلقي الملف الأصلي، والبيانات الوصفية تسافر معه.</p>\n<p>والتعديل وإعادة التصدير يختلف: بعض المحررين يحافظون على EXIF وآخرون يزيلونه وآخرون يوفرون اختيارًا: لا تفترض أبدًا أن صورة معدلة نظيفة دون مراجعتها. ولقطات الشاشة ليس لها أبدًا: الحافظة تمرر بكسلات خامًا، فاللقطة تحمل فقط أبعادًا وصيغة، دون كتل كاميرا ولا GPS.</p>\n<h2 id=\"practical-routine\">روتين خصوصية عملي</h2>\n<p>خصوصية صور جيدة روتين لا حل مرة واحدة: خمس عادات تغطي كل المخاطر تقريبًا، وكل منها تستغرق ثوانٍ.</p>\n<p>أولًا، راجع قبل المشاركة: اسحب الملف الأصلي إلى <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a> واقرأ إشعار الملخص وتنبيه GPS. وثانيًا، أزل الحساس: استخدم أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>، وأبقِ Lossless Binary Strip لـJPG وPNG، واستخدم Full Canvas Re-encode لـWebP وHEIC أو تغييرات الصيغة.</p>\n<p>وثالثًا، تحقق من الملف النظيف: أعد مراجعة النسخة المنزلة وأكد الإشعار الأخضر: لم تُكتشف وسوم EXIF أو GPS أو كاميرا مخفية. ورابعًا، راجع البكسلات نفسها: قص أرقام شوارع وأزياء مدرسية ولوحات سيارات وخلفيات مميزة، أو موّهها قبل المشاركة.</p>\n<p>وخامسًا، عطّل موقع الكاميرا حيث لا تحتاجه: تعطيل الموقع لتطبيق الكاميرا يوقف وسوم GPS من المصدر، وهي الحماية الأكثر موثوقية من كلها.</p>\n<p>لعملية التنظيف خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-izala-bayanat-min-as-sura/\">كيف تزيل البيانات الوصفية من صورة</a>. وللدليل الكامل للأداة، اقرأ <a href=\"/ar/blog/dalil-izala-bayanat-as-suwar/\">إزالة البيانات الوصفية من الصور: دليل كامل</a>.</p>\n<h2 id=\"beyond-metadata\">أبعد من البيانات الوصفية: ماذا يتسرب أيضًا؟</h2>\n<p>البيانات الوصفية تسرب واحد، لكن الصور تتسرب بطرق أخرى أيضًا: مراجعة خصوصية كاملة تنظر إلى الصورة كلها.</p>\n<p>المعرفات المرئية هي الأكثر وضوحًا: أرقام منازل ولافتات شوارع وشعارات مدارس ولوحات سيارات وبريد باسمك كلها مرئية في البكسلات. والانعكاسات قد تكشف ما خلف الكاميرا: مرآة أو نافذة أو سطح مصقول قد يُظهر وجهًا أو غرفة أو موقعًا لم يقصد المصور مشاركته أبدًا.</p>\n<p>والخلفيات تكشف سياقًا: مبنى مميز أو جبل أو تخطيط شارع قد يحدد مكانًا حتى دون بيانات GPS، خاصة مدمجًا مع طابع زمني. وأسماء الملفات قد تتسرب أيضًا: صورة باسم يشمل تاريخًا أو مكانًا أو اسم شخص تحمل تلك المعلومات في الاسم نفسه، حتى بعد إزالة البيانات الوصفية.</p>\n<p>وإزالة البيانات الوصفية أساسية، لكنها طبقة واحدة: اجمعها مع نظرة سريعة إلى الصورة نفسها قبل كل نشر.</p>\n<h2 id=\"law-and-photos\">القانون والموافقة وصورك</h2>\n<p>قانون الخصوصية يختلف حسب البلد، لكن القاعدة العملية متسقة: أنت مسؤول عما تنشره، بما فيه البيانات المخفية داخل ملفاتك.</p>\n<p>نشر صورة بإحداثيات GPS هو، في معظم الأماكن، قرارك الخاص بنشر ذلك الموقع: القانون نادرًا يحمي معلومات شاركتها بنفسك، حتى دون معرفة. وصور أشخاص آخرين تضيف الموافقة إلى الصورة: بالغ وافق على التصوير لم يوافق بالضرورة على نشر موقعه أو روتينه اليومي.</p>\n<p>وصور الأطفال تحمل توقعات أشد في كل مكان تقريبًا: مدارس ونوادٍ وآباء يعاملون بيانات الموقع في صور الأطفال بشكل متزايد كموضوع حماية، لا كتفصيل تقني. وبالنسبة للشركات، ما هو على المحك يشمل أمن الموظفين: صورة منتج ملتقطة داخل مستودع قد تكشف موقع المستودع، وصورة فريق قد تكشف من يعمل هناك.</p>\n<p>ولا شيء من هذا يحتاج محاميًا لحله: راجع ونظف وتحقق قبل المشاركة، واطلب موافقة قبل نشر صور أشخاص آخرين، خاصة أطفال.</p>\n<h2 id=\"building-habit\">كيف تبني العادة</h2>\n<p>عادات الخصوصية تفشل عندما تشعر كعمل إضافي: الحيلة ربط المراجعة بخطوة تتخذها أصلًا، لتحدث تلقائيًا.</p>\n<p>اربطها بخطوة التصدير: عندما تصدّر صورة للنشر، مرّرها عبر العارض والمنظف قبل أن تصل إلى التطبيق الاجتماعي. واربطها بخطوة الإعلان: عندما تجهّز صورًا لإعلان، نظف الدفعة كلها ونزّل ZIP كجزء من نفس الروتين.</p>\n<p>واربطها بخطوة المشاركة: قبل إرسال صورة كمرفق بريد أو نقل ملفات، نظفها أولًا، لأن تلك الطرق تحافظ على البيانات الوصفية.</p>\n<p>وبعد أسبوع، يأخذ الروتين ثوانٍ ويشعر بالتلقائية: التكلفة ضئيلة، والحماية تغطي كل صورة تشاركها بعدها.</p>\n<h2 id=\"photo-privacy-summary\">في الخلاصة</h2>\n<p>صورك تحمل إحداثيات GPS وطوابع زمنية وهوية كاميرا وسجل تعديل في بياناتها الوصفية المخفية: وأي شخص ينزّل الملف يستطيع قراءتها بعارض مجاني.</p>\n<p>تطبيقات التواصل الاجتماعي تزيل هذه البيانات تلقائيًا، لكن البريد والمتاجر عبر الإنترنت والمنتديات وروابط السحابة غالبًا لا تفعل: والخطر أكبر لصور أطفال وصور ملتقطة في المنزل أو المدرسة أو العمل.</p>\n<p>راجع كل صورة في <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a> ونظفها بأداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> وتحقق من النسخة النظيفة قبل المشاركة: يجب أن تُظهر صورك للعالم ما قررت مشاركته، ولا شيء أكثر.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يستطيع أحد إيجاد عنوان منزلي من صورة نشرتها؟","answer":"نعم، إذا ما زالت الصورة تحمل إحداثيات GPS: يفك عارضها إلى خط عرض وخط طول، تشير إلى نقطة دقيقة، غالبًا منزلك. وهذا أكثر احتمالًا مع إعلانات متاجر عبر الإنترنت ومنشورات منتديات ومرفقات بريد."},{"question":"هل يكفي تعطيل خدمات الموقع لكاميرتي؟","answer":"تعطيل موقع الكاميرا يوقف وسوم GPS من المصدر، وهي الحماية الأكثر موثوقية ضد تسرب الموقع: ولا يزيل حقول EXIF الأخرى، مثل الطوابع الزمنية وموديل الكاميرا وحقول البرنامج. وراجع الصور القديمة ونظفها أيضًا."},{"question":"هل صور أستلمها من آخرين تعرض خصوصيتي للخطر؟","answer":"ليس مباشرة: بياناتها الوصفية تصف صورتها لا صورتك. لكن إذا أعدت إرسال تلك الصورة، تمرر أيضًا بياناتها الوصفية: صورة أرسلها لك أحد قد تحمل إحداثيات منزله، وإعادة إرسالها تنشر تلك البيانات أكثر."},{"question":"هل تستطيع بيانات صورة وصفية كشف هويتي حتى دون GPS؟","answer":"نعم، مدمجة: رقم تسلسلي للكاميرا يربط صورًا بجهاز واحد. والطوابع الزمنية تكشف روتينًا. وحقول البرنامج تكشف أدواتك. واسم فنان أو مالك قد يكون اسمًا حقيقيًا. ومعًا تبني ملفًا."},{"question":"هل يجب على الشركات إزالة البيانات الوصفية من صور المنتجات؟","answer":"نعم، صور منتجات ملتقطة في منزل أو مستودع أو مكتب قد تحمل إحداثيات GPS تشير إلى ذلك العنوان: وقد تحمل أيضًا طوابع زمنية تُظهر ساعات عمل وتفاصيل عن عملياتك. ونظف دفعات المنتج قبل النشر."},{"question":"هل حذف صورة منشورة يزيل الخطر؟","answer":"ليس تمامًا: بمجرد أن تصبح صورة عامة، قد يكون أي شخص نزّل الأصل ببياناته الوصفية سليمة. وحذف المنشور يوقف تنزيلات جديدة، لكن النسخ المحفوظة أصلًا في أماكن أخرى تبقى."}];
